CREATE TABLE public.user_path_rewards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, module_id uuid NOT NULL REFERENCES public.education_modules(id) ON DELETE CASCADE, reward_type text NOT NULL CHECK (reward_type IN ('xp','streak_freeze')), reward_value integer NOT NULL CHECK (reward_value > 0), claimed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,module_id));
GRANT SELECT ON public.user_path_rewards TO authenticated;
GRANT ALL ON public.user_path_rewards TO service_role;
ALTER TABLE public.user_path_rewards ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Users read own path rewards" ON public.user_path_rewards FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE OR REPLACE FUNCTION public.get_practice_questions(_module_id uuid, _limit integer DEFAULT 5) RETURNS TABLE(id uuid,module_id uuid,question text,options jsonb,order_index integer,section_id uuid,is_checkpoint boolean,position_in_section integer,exercise_type text) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; RETURN QUERY SELECT q.id,q.module_id,q.question,q.options,q.order_index,q.section_id,q.is_checkpoint,q.position_in_section,q.exercise_type FROM public.quiz_questions q WHERE q.module_id=_module_id ORDER BY EXISTS(SELECT 1 FROM public.user_quiz_performance p WHERE p.user_id=auth.uid() AND p.question_id=q.id AND NOT p.is_correct) DESC,random() LIMIT greatest(0,least(coalesce(_limit,5),5)); END $$;
REVOKE ALL ON FUNCTION public.get_practice_questions(uuid,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_practice_questions(uuid,integer) TO authenticated;
CREATE OR REPLACE FUNCTION public.claim_path_chest(_module_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ DECLARE reward public.user_path_rewards%ROWTYPE; roll float8; kind text; value integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text,1));
IF (SELECT count(DISTINCT s.section_number) FROM public.module_sections s JOIN public.user_section_progress p ON p.section_id=s.id AND p.user_id=auth.uid() AND p.completed WHERE s.module_id=_module_id AND s.section_number IN (1,2)) <> 2 THEN RAISE EXCEPTION 'Chest is still locked'; END IF;
SELECT * INTO reward FROM public.user_path_rewards WHERE user_id=auth.uid() AND module_id=_module_id;
IF FOUND THEN RETURN jsonb_build_object('reward_type',reward.reward_type,'reward_value',reward.reward_value); END IF;
roll:=random(); kind:='xp'; value:=CASE WHEN roll < .45 THEN 10 WHEN roll < .75 THEN 15 WHEN roll < .90 THEN 20 WHEN roll < .95 THEN 25 ELSE 1 END; IF roll >= .95 THEN kind:='streak_freeze'; END IF;
INSERT INTO public.user_learning_stats(user_id) VALUES(auth.uid()) ON CONFLICT(user_id) DO NOTHING;
INSERT INTO public.user_path_rewards(user_id,module_id,reward_type,reward_value) VALUES(auth.uid(),_module_id,kind,value);
IF kind='xp' THEN INSERT INTO public.xp_transactions(user_id,xp_amount,source,source_id) VALUES(auth.uid(),value,'path_chest',_module_id::text); UPDATE public.user_learning_stats SET total_xp=total_xp+value,current_level=public.level_for_xp(total_xp+value),updated_at=now() WHERE user_id=auth.uid(); ELSE UPDATE public.user_learning_stats SET streak_freezes=streak_freezes+1,updated_at=now() WHERE user_id=auth.uid(); END IF;
RETURN jsonb_build_object('reward_type',kind,'reward_value',value); END $$;
REVOKE ALL ON FUNCTION public.claim_path_chest(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_path_chest(uuid) TO authenticated;